import React, { Fragment } from 'react';
import MarkdownPreview from 'component/common/markdown-preview';
import ClaimTags from 'component/claimTags';
import CreditAmount from 'component/common/credit-amount';
import Button from 'component/button';
import * as PAGES from 'constants/pages';
import DateTime from 'component/dateTime';
import YoutubeBadge from 'component/youtubeBadge';
import SUPPORTED_LANGUAGES from 'constants/supported_languages';
import { useAppSelector } from 'redux/hooks';
import { makeSelectMetadataItemForUri, makeSelectClaimForUri, selectClaimIsMine } from 'redux/selectors/claims';
import { selectUser } from 'redux/selectors/user';
type Props = {
  uri: string;
  channelIsBlackListed: boolean;
};

const formatEmail = (email: string) => {
  if (email) {
    const protocolRegex = new RegExp('^mailto:', 'i');
    const protocol = protocolRegex.exec(email);
    return protocol ? email : `mailto:${email}`;
  }

  return null;
};

const formatWebsite = (website: string) => {
  if (website) {
    const protocolRegex = new RegExp('^https://', 'i');
    const protocol = protocolRegex.exec(website);
    return protocol ? website : `https://${website}`;
  }

  return null;
};

function AboutTab(props: Props) {
  const { uri, channelIsBlackListed } = props;
  const claim = useAppSelector((state) => makeSelectClaimForUri(uri)(state));
  const description = useAppSelector((state) => makeSelectMetadataItemForUri(uri, 'description')(state));
  const website = useAppSelector((state) => makeSelectMetadataItemForUri(uri, 'website_url')(state));
  const email = useAppSelector((state) => makeSelectMetadataItemForUri(uri, 'email')(state));
  const languages = useAppSelector((state) => makeSelectMetadataItemForUri(uri, 'languages')(state));
  const user = useAppSelector(selectUser);
  const claimIsMine = useAppSelector((state) => selectClaimIsMine(state, claim));
  const claimId = claim && claim.claim_id;
  const canView = user && user.global_mod;

  // If channel is blacklisted, only show the DMCA message
  if (channelIsBlackListed) {
    return (
      <div className="card">
        <section className="card--section dmca-info">
          <p>
            {__(
              'In response to a complaint we received under the US Digital Millennium Copyright Act, we have blocked access to this channel from our applications. Content may also be blocked due to DMCA Red Flag rules which are obvious copyright violations we come across, are discussed in public channels, or reported to us.'
            )}
          </p>
          {claimIsMine && (
            <p>
              {__('Please remove the content, or reach out to %email% if you think there has been a mistake.', {
                email: 'help@odysee.com',
              })}
            </p>
          )}
          <div className="section__actions">
            <Button
              button="link"
              href="https://help.odysee.tv/category-uploading/dmca-content/#receiving-a-dmca-notice"
              label={__('Read More')}
            />
          </div>
        </section>
      </div>
    );
  }

  return (
    <div className="card">
      <section className="section card--section">
        <Fragment>
          {description && (
            <>
              <label>{__('Description')}</label>
              <div className="media__info-text media__info-text--constrained">
                <MarkdownPreview content={description} />
              </div>
            </>
          )}
          {email && (
            <Fragment>
              <label>{__('Contact')}</label>
              <div className="media__info-text">
                <MarkdownPreview content={formatEmail(email)} simpleLinks />
              </div>
            </Fragment>
          )}
          {website && (
            <Fragment>
              <label>{__('Site')}</label>
              <div className="media__info-text">
                <MarkdownPreview content={formatWebsite(website)} simpleLinks />
              </div>
            </Fragment>
          )}

          <label>{__('Tags')}</label>
          <div className="media__info-text">
            <ClaimTags uri={uri} type="large" />
          </div>

          {languages && languages.length && (
            <>
              <label>{__('Languages')}</label>
              <div className="media__info-text">
                {languages.reduce((acc, lang, i) => {
                  return acc + `${SUPPORTED_LANGUAGES[lang] || lang} `;
                }, '')}
              </div>
            </>
          )}

          <label>{__('Total Uploads')}</label>
          <div className="media__info-text">{claim.meta.claims_in_channel}</div>

          <label>{__('Created At')}</label>
          <div className="media__info-text">
            <DateTime timeAgo uri={uri} />
          </div>

          <label>{__('URL')}</label>
          <div className="media__info-text">
            <div className="media__info-text media__info-text--constrained">{claim.canonical_url}</div>
          </div>

          <label>{__('Claim ID')}</label>
          <div className="media__info-text">
            <div className="media__info-text media__info-text--constrained">{claim.claim_id}</div>
          </div>

          <label>{__('Staked Credits')}</label>
          <div className="media__info-text">
            <CreditAmount amount={parseFloat(claim.amount) + parseFloat(claim.meta.support_amount)} precision={8} />{' '}
            <Button
              button="link"
              label={__('view other claims at lbry://%name%', {
                name: claim.name,
              })}
              navigate={`/$/${PAGES.TOP}?name=${claim.name}`}
            />
          </div>
          {canView && <YoutubeBadge channelClaimId={claimId} />}
        </Fragment>
      </section>
    </div>
  );
}

export default AboutTab;
