import React from 'react';
import classnames from 'classnames';
import Button from 'component/button';
import * as ICONS from 'constants/icons';
import * as CS from 'constants/claim_search';
import HomeTabSection from './internal/homeTabSection';
import CollectionEditButtons from 'component/collectionEditButtons';
import LivestreamLink from 'component/livestreamLink';
import './style.scss';
import { useAppSelector, useAppDispatch } from 'redux/hooks';
import {
  selectClaimForUri,
  selectClaimSearchByQuery,
  makeSelectTagInClaimOrChannelForUri,
} from 'redux/selectors/claims';
import { doResolveUris } from 'redux/actions/claims';
import { selectSettingsByChannelId } from 'redux/selectors/comments';
import { doUpdateCreatorSettings as doUpdateCreatorSettingsAction } from 'redux/actions/comments';
import { PREFERENCE_EMBED } from 'constants/tags';
type Props = {
  uri: string;
  editMode: boolean;
  handleViewMore: (arg0: any) => void;
};

function HomeTab(props: Props) {
  const { uri, editMode, handleViewMore } = props;
  const dispatch = useAppDispatch();
  const claim = useAppSelector((state) => uri && selectClaimForUri(state, uri));
  const settingsByChannelId = useAppSelector(selectSettingsByChannelId);
  const preferEmbed = useAppSelector((state) => makeSelectTagInClaimOrChannelForUri(uri, PREFERENCE_EMBED)(state));
  const doUpdateCreatorSettings = (channelClaim: ChannelClaim, settings: PerChannelSettings) =>
    dispatch(doUpdateCreatorSettingsAction(channelClaim, settings));
  const claimId = claim && claim.claim_id;
  const rawHomepageSettings =
    settingsByChannelId && settingsByChannelId[claim.claim_id] && settingsByChannelId[claim.claim_id].homepage_settings;
  // Backward compat: homepage_settings can be an array (old) or object (new { sections, upload_templates }).
  const homepageSections = React.useMemo(() => {
    if (!rawHomepageSettings) return null;
    if (Array.isArray(rawHomepageSettings)) return rawHomepageSettings;
    const sections = rawHomepageSettings.sections;
    return Array.isArray(sections) ? sections : null;
  }, [rawHomepageSettings]);
  const homeTemplate = React.useMemo(
    () => [
      {
        type: 'featured',
        file_type: undefined,
        order_by: CS.ORDER_BY_TOP_VALUE,
        claim_id: undefined,
        rows: 1,
      },
      {
        type: 'content',
        file_type: CS.FILE_TYPES,
        order_by: CS.ORDER_BY_NEW_VALUE,
        claim_id: undefined,
        rows: 2,
      },
    ],
    []
  );
  const [home, setHome] = React.useState([]);
  const [edit, setEdit] = React.useState(false);
  const topContentGridIndex = 1;
  React.useEffect(() => {
    if (edit || !claimId || !settingsByChannelId?.[claimId]) {
      return;
    }

    const nextHome = homepageSections || homeTemplate;
    setHome((prevHome) => (JSON.stringify(prevHome) === JSON.stringify(nextHome) ? prevHome : nextHome));
  }, [claimId, edit, homeTemplate, homepageSections, settingsByChannelId]);

  function handleEditCollection(e: any, index?: any) {
    let newHome = [...home];

    if (e.order) {
      if (e.order.to >= newHome.length) {
        var k = e.order.to - newHome.length + 1;

        while (k--) {
          newHome.push(undefined);
        }
      }

      newHome.splice(e.order.to, 0, newHome.splice(e.order.from, 1)[0]);
    } else if (e.delete) {
      newHome.splice(e.delete.index, 1);
    } else if (e.change) {
      if (e.change.field && e.change.field !== 'order_by') {
        if (e.change.field === 'type') {
          newHome[index] = {
            type: e.change.value,
            file_type:
              e.change.value === 'content' ? CS.FILE_TYPES : e.change.value === 'reposts' ? CS.CLAIM_REPOST : undefined,
            order_by: CS.ORDER_BY_NEW_VALUE,
            claim_id: undefined,
            rows: e.change.value === 'content' || e.change.value === 'reposts' ? 2 : 1,
          };
        } else if (e.change.field === 'file_type') {
          newHome[index][e.change.field] = e.change.value.split(',');
        } else {
          newHome[index][e.change.field] = e.change.value;
        }
      } else {
        newHome[index][e.change.field] = [e.change.value];
      }
    }

    setHome(newHome);
  }

  function handleAddHomeSection(e) {
    let newHome = [...home];
    newHome.push({
      type: undefined,
      file_type: CS.FILE_TYPES,
      order_by: CS.ORDER_BY_NEW_VALUE,
      claim_id: undefined,
      rows: 1,
    });
    setHome(newHome);
  }

  function handleSaveHomeSection() {
    setHome(home);
    // Preserve any non-section data in homepage_settings (e.g. upload_templates)
    const existingObj = rawHomepageSettings && !Array.isArray(rawHomepageSettings) ? rawHomepageSettings : {};
    doUpdateCreatorSettings(claim, {
      homepage_settings: { ...existingObj, sections: home },
    });
    setEdit(false);
  }

  function handleCancelChanges() {
    setHome(homepageSections || (settingsByChannelId && homeTemplate) || []);
    setEdit(false);
  }

  return (
    settingsByChannelId && (
      <div className="home-tab">
        {editMode && (
          <div className="channel_sections__actions">
            <Button
              label={__('Edit Home Tab')}
              button="primary"
              icon={ICONS.EDIT}
              disabled={edit}
              onClick={() => {
                setEdit(!edit);
              }}
            />
          </div>
        )}

        {!edit && <LivestreamLink uri={props.uri} />}

        {home &&
          !preferEmbed &&
          home.map((section, i) => {
            return (
              <div
                key={i}
                className={classnames('home-section-wrapper', {
                  'home-section-wrapper--edit': edit,
                  'home-section-wrapper--edit-featured': edit && section?.type === 'featured',
                  'home-section-wrapper--edit-content': edit && section?.type === 'content',
                  'home-section-wrapper--edit-playlist': edit && section?.type === 'playlist',
                  'home-section-wrapper--edit-playlists': edit && section?.type === 'playlists',
                  'home-section-wrapper--edit-onerow':
                    edit &&
                    section?.type !== 'content' &&
                    section?.type !== 'featured' &&
                    section?.type !== 'playlist' &&
                    section?.type !== 'playlists',
                })}
              >
                <div className="order">
                  {edit && (
                    <CollectionEditButtons
                      altIndex={i}
                      altCollection={home}
                      altEditCollection={(e) => handleEditCollection(e)}
                    />
                  )}
                </div>
                <HomeTabSection
                  channelClaimId={claimId}
                  section={section}
                  editMode={edit}
                  index={i}
                  topContentGridIndex={topContentGridIndex}
                  hasFeaturedContent={home.some((s) => s?.type === 'featured')}
                  handleEditCollection={(e) => handleEditCollection(e, i)}
                  handleViewMore={(e) => handleViewMore(e)}
                />
              </div>
            );
          })}
        {edit && (
          <div className="home-tab-edit">
            <Button label={__('Save')} button="primary" onClick={() => handleSaveHomeSection()} />
            <Button button="link" label={__('Cancel')} onClick={handleCancelChanges} />
          </div>
        )}
        {edit && (
          <Button label={__('Add New Section')} button="primary" icon={ICONS.ADD} onClick={handleAddHomeSection} />
        )}
      </div>
    )
  );
}

export default HomeTab;
