import React from 'react';
import ClaimListDiscover from 'component/claimListDiscover';
import FeaturedSection from '../featuredSection';
import { useWindowSize } from 'effects/use-screensize';
import { DEBOUNCE_WAIT_DURATION_MS, SEARCH_PAGE_SIZE } from 'constants/search';
import ChannelSection from 'component/channelSections/Section';
import UpcomingClaims from 'component/upcomingClaims';
import ClaimPreviewTile from 'component/claimPreviewTile';
import { lighthouse } from 'redux/actions/search';
import * as CS from 'constants/claim_search';
import Icon from 'component/common/icon';
import * as ICONS from 'constants/icons';
import { Container } from 'util/container';
import { useAppSelector, useAppDispatch } from 'redux/hooks';
import {
  doClaimSearch as doClaimSearchAction,
  doResolveClaimId as doResolveClaimIdAction,
  doResolveUris as doResolveUrisAction,
} from 'redux/actions/claims';
import { doFetchThumbnailClaimsForCollectionIds as doFetchThumbnailClaimsForCollectionIdsAction } from 'redux/actions/collections';
import { selectActiveLivestreamForChannel } from 'redux/selectors/livestream';
import { createNormalizedClaimSearchKey } from 'util/claim';
import {
  selectClaimSearchByQuery,
  selectFetchingClaimSearchByQuery,
  selectClaimUriForId,
} from 'redux/selectors/claims';
import {
  selectUrlsForCollectionId,
  selectCollectionTitleForId,
  selectMyPublishedCollections,
  selectClaimIdsForCollectionId,
} from 'redux/selectors/collections';
import { SECTION_TAGS } from 'constants/collections';
import { selectFeaturedChannelsForChannelId } from 'redux/selectors/comments';
import { CsOptHelper } from 'util/claim-search';
type Props = {
  channelClaimId: any;
  index: number;
  topContentGridIndex: number;
  section: any;
  editMode: boolean;
  hasFeaturedContent: boolean;
  handleEditCollection: (arg0: any) => void;
  handleViewMore: (arg0: any) => void;
};

function HomeTabSection(props: Props) {
  const { channelClaimId, index, section, editMode, hasFeaturedContent, handleEditCollection, handleViewMore } = props;
  const dispatch = useAppDispatch();

  // Build search options (mirrors old index.ts logic)
  const stream_types =
    section.file_type && Array.isArray(section.file_type)
      ? section.file_type
      : section.file_type
        ? [section.file_type]
        : undefined;
  const claimType = section.type === 'playlists' ? 'collection' : section.type === 'reposts' ? 'repost' : 'stream';
  const options = React.useMemo(
    () => ({
      page_size: section.type !== 'featured' ? 12 : 1,
      page: 1,
      channel_ids: [channelClaimId],
      stream_types: section.type !== 'reposts' ? stream_types : undefined,
      claim_type: claimType,
      order_by: section.order_by || ['effective_amount'],
      not_tags:
        section.type === 'playlists'
          ? CsOptHelper.not_tags({ notTags: [SECTION_TAGS.FEATURED_CHANNELS] })
          : CsOptHelper.not_tags(),
      any_tags: section.type === 'channels' ? [SECTION_TAGS.FEATURED_CHANNELS] : undefined,
      no_totals: true,
      index,
      has_source: true,
      duration: CsOptHelper.duration(null, claimType, CS.DURATION.ALL as import('constants/claim_search').Duration),
    }),
    [channelClaimId, section.type, section.order_by, section.file_type, index, stream_types, claimType]
  );
  const searchKey = createNormalizedClaimSearchKey(options);
  const requiresSearch =
    section.type === 'content' ||
    section.type === 'playlists' ||
    section.type === 'reposts' ||
    (section.type === 'featured' && !section.claim_id);
  const fetchingClaimSearch = useAppSelector((state) =>
    requiresSearch ? selectFetchingClaimSearchByQuery(state)[searchKey] : undefined
  );
  const claimSearchResults = useAppSelector((state) =>
    requiresSearch && !section.claim_id ? selectClaimSearchByQuery(state)[searchKey] : undefined
  );
  const activeLivestream = useAppSelector((state) => selectActiveLivestreamForChannel(state, channelClaimId));
  const activeLivestreamUri = activeLivestream?.uri;
  const optionsStringified = JSON.stringify(options);
  const collectionUrls = useAppSelector((state) =>
    section.type === 'playlist' && section.claim_id ? selectUrlsForCollectionId(state, section.claim_id) : undefined
  );
  const collectionClaimIds = useAppSelector((state) =>
    section.type === 'playlist' && section.claim_id ? selectClaimIdsForCollectionId(state, section.claim_id) : undefined
  );
  const collectionName = useAppSelector((state) =>
    section.type === 'playlist' ? selectCollectionTitleForId(state, section.claim_id) : undefined
  );
  const publishedCollections = useAppSelector(selectMyPublishedCollections);
  const singleClaimUriFromState = useAppSelector((state) =>
    section.type === 'featured' && section.claim_id ? selectClaimUriForId(state, section.claim_id) : undefined
  );
  const singleClaimUri = section.type === 'featured' && section.claim_id && singleClaimUriFromState;
  const featuredChannels = useAppSelector((state) => selectFeaturedChannelsForChannelId(state, channelClaimId));

  const doClaimSearch = (searchOptions: ClaimSearchOptions, settings?: DoClaimSearchSettings | null) =>
    dispatch(doClaimSearchAction(searchOptions, settings));
  const doResolveClaimId = (id: string) => dispatch(doResolveClaimIdAction(id));
  const doResolveUris = (uris: Array<string>) => dispatch(doResolveUrisAction(uris));
  const doFetchThumbnailClaimsForCollectionIds = (params: { collectionIds: Array<string> }) =>
    dispatch(doFetchThumbnailClaimsForCollectionIdsAction(params));
  const timedOut = claimSearchResults === null;
  const shouldPerformSearch =
    !singleClaimUri && !fetchingClaimSearch && !timedOut && !claimSearchResults && !collectionUrls && section;
  const shouldResolveCollectionClaims = Boolean(!collectionClaimIds && collectionUrls);
  const publishedList = Object.keys(publishedCollections || {}) as any;
  const maxClaimsInSection = 12;
  const windowSize = useWindowSize();
  const maxChannelsPerRow = windowSize >= 1150 ? 8 : windowSize > 900 ? 6 : 3;
  const featuredChannel = featuredChannels && featuredChannels.find((list) => list.id === section.claim_id);
  const hasFeaturedClaim = singleClaimUri || (claimSearchResults && claimSearchResults[0]) || section.claim_id;
  const scheduledChanIds = React.useMemo(() => [channelClaimId], [channelClaimId]);
  const liveUris = React.useMemo(() => {
    // This follows `contentTab` where it assumes only 1 livestream per channel.
    return activeLivestreamUri ? [activeLivestreamUri] : Container.Arr.EMPTY;
  }, [activeLivestreamUri]);
  React.useEffect(() => {
    if (shouldPerformSearch) {
      const searchOptions = JSON.parse(optionsStringified);
      const searchSettings = {
        fetch: {
          viewCount: true,
        },
      };
      dispatch(doClaimSearchAction(searchOptions, searchSettings)).then((res) => {
        if (section.type === 'playlists' && res) {
          const streams = Object.values(res);
          const claimIds = streams.map((s: any) => s?.stream?.claim_id);
          dispatch(
            doFetchThumbnailClaimsForCollectionIdsAction({
              collectionIds: claimIds,
            })
          );
        }
      });
    } // eslint-disable-next-line react-hooks/exhaustive-deps -- DOESN'T FEEL RIGHT WITHOUT optionsStringified
  }, [dispatch, shouldPerformSearch]);
  React.useEffect(() => {
    if (section.claim_id) {
      doResolveClaimId(section.claim_id);
    } // eslint-disable-next-line react-hooks/exhaustive-deps -- @see TODO_NEED_VERIFICATION
  }, [section]);
  React.useEffect(() => {
    if (shouldResolveCollectionClaims) {
      doResolveUris(collectionUrls);
    } // eslint-disable-next-line react-hooks/exhaustive-deps -- @see TODO_NEED_VERIFICATION
  }, [shouldResolveCollectionClaims]);
  const [searchQuery, setSearchQuery] = React.useState('');
  const [isSearching, setIsSearching] = React.useState(false);
  const [searchResults, setSearchResults] = React.useState(undefined);

  function handleInputChange(e) {
    const { value } = e.target;
    setSearchQuery(value);
  }

  React.useEffect(() => {
    const timer = setTimeout(() => {
      if (searchQuery.trim().length < 3 || !channelClaimId) {
        return setSearchResults(null);
      }

      setIsSearching(true);
      lighthouse
        .search(
          `&s=${encodeURIComponent(searchQuery)}` +
            `&channel_id=${encodeURIComponent(channelClaimId)}` +
            '&nsfw=false' +
            '&resolve=true' +
            `&size=${SEARCH_PAGE_SIZE}`
        )
        .then(({ body: results }) => {
          setSearchResults(results);
        })
        .catch(() => {
          setSearchResults(null);
        })
        .finally(() => {
          setIsSearching(false);
        });
    }, DEBOUNCE_WAIT_DURATION_MS);
    return () => clearTimeout(timer); // eslint-disable-next-line react-hooks/exhaustive-deps -- @see TODO_NEED_VERIFICATION (definitely needs channelClaimId, no?)
  }, [searchQuery]);

  function getTitle() {
    switch (section.type) {
      case 'featured':
        return null;

      case 'content':
        switch (section.file_type.length === 1 && section.file_type[0]) {
          case CS.FILE_VIDEO:
            switch (section.order_by ? section.order_by[0] : 'release_time') {
              case 'release_time':
                return __('New Videos');

              case 'trending_group':
                return __('Trending Videos');

              case 'effective_amount':
                return __('Top Videos');

              default:
                return __('Videos');
            }

          case CS.FILE_AUDIO:
            switch (section.order_by ? section.order_by[0] : 'release_time') {
              case 'release_time':
                return __('New Audio');

              case 'trending_group':
                return __('Trending Audio');

              case 'effective_amount':
                return __('Top Audio');

              default:
                return __('Audio');
            }

          case CS.FILE_IMAGE:
            switch (section.order_by ? section.order_by[0] : 'release_time') {
              case 'release_time':
                return __('New Images');

              case 'trending_group':
                return __('Trending Images');

              case 'effective_amount':
                return __('Top Images');

              default:
                return __('Images');
            }

          case CS.FILE_DOCUMENT:
            switch (section.order_by ? section.order_by[0] : 'release_time') {
              case 'release_time':
                return __('New Posts');

              case 'trending_group':
                return __('Trending Posts');

              case 'effective_amount':
                return __('Top Posts');

              default:
                return __('Posts');
            }

          default:
            switch (section.order_by ? section.order_by[0] : 'release_time') {
              case 'release_time':
                return __('New Content');

              case 'trending_group':
                return __('Trending Content');

              case 'effective_amount':
                return __('Top Content');
            }
        }

        break;

      case 'playlists':
        return __('Playlists');

      case 'channels':
        return (
          featuredChannels &&
          featuredChannels.find((list) => list.id === section.claim_id) &&
          featuredChannels.find((list) => list.id === section.claim_id).value.title
        );

      case 'reposts':
        return __('Reposts');
    }
  }

  // Determine if we should show loading state based on section type:
  // - Sections requiring search: only show loading if actively fetching
  // - 'playlist' type: only show loading if claim_id exists and data is pending
  // - 'channels' type: don't show loading (data either exists or doesn't)
  // - If no claim_id for playlist, or no data source configured, don't show loading
  const isLoading = (() => {
    if (!section.type || section.type === 'featured') return false;

    if (requiresSearch) {
      // Only show loading during active fetch, not when results are empty/missing
      return fetchingClaimSearch;
    }

    // For 'playlist' type: need claim_id to load anything
    if (section.type === 'playlist') {
      return section.claim_id && !collectionClaimIds && !collectionUrls;
    }

    // For 'channels' type: don't show loading skeleton
    if (section.type === 'channels') {
      return false;
    }

    return false;
  })();

  return (
    <div className="home-section-content">
      {!editMode && index === 0 && (
        <UpcomingClaims
          name="homeTab"
          channelIds={scheduledChanIds}
          tileLayout={false}
          showHideSetting={false}
          liveUris={liveUris}
          isChannelPage
        />
      )}
      {editMode && (
        <div className="home-section-header-wrapper">
          <div className="home-section-header-option">
            <label>{__('Type')}</label>
            <select
              name="type"
              value={section.type || 'select'}
              onChange={(e) =>
                handleEditCollection({
                  change: {
                    field: e.target.name,
                    value: e.target.value,
                  },
                })
              }
            >
              <option value="select" disabled>
                {__('Select')}
              </option>
              <option value="featured" disabled={hasFeaturedContent}>
                {__('Featured')}
              </option>
              <option value="content">{__('Content')}</option>
              <option value="playlists">{__('Playlists')}</option>
              <option value="playlist">{__('Playlist')}</option>
              <option value="channels" disabled={!featuredChannels}>
                {__('Channels')}
              </option>
              <option value="reposts">{__('Reposts')}</option>
            </select>
          </div>
          {section.type === 'content' && (
            <div className="home-section-header-option">
              <label>{__('File Type')}</label>
              <select
                name="file_type"
                value={section.file_type || CS.FILE_TYPES}
                onChange={(e) =>
                  handleEditCollection({
                    change: {
                      field: e.target.name,
                      value: e.target.value,
                    },
                  })
                }
              >
                <option value={CS.FILE_TYPES}>{__('Show All')}</option>
                <option value={CS.FILE_VIDEO}>{__('Videos')}</option>
                <option value={CS.FILE_AUDIO}>{__('Audio')}</option>
                <option value={CS.FILE_DOCUMENT}>{__('Posts')}</option>
                <option value={CS.FILE_IMAGE}>{__('Images')}</option>
              </select>
            </div>
          )}
          {section.type === 'playlist' && (
            <div className="home-section-header-option">
              <label>{__('Playlist')}</label>
              <select
                name="claim_id"
                value={section.claim_id || 'select'}
                onChange={(e) =>
                  handleEditCollection({
                    change: {
                      field: e.target.name,
                      value: e.target.value,
                    },
                  })
                }
              >
                <option value="select">{__('Select a Playlist')}</option>
                {publishedList &&
                  publishedList.map((list, i) => {
                    return (
                      <option key={i} value={list}>
                        {publishedCollections[list].name}
                      </option>
                    );
                  })}
              </select>
            </div>
          )}
          {section.type === 'channels' && (
            <div className="home-section-header-option">
              <label>{__('Featured Channels')}</label>
              <select
                name="claim_id"
                value={section.claim_id || 'select'}
                onChange={(e) =>
                  handleEditCollection({
                    change: {
                      field: e.target.name,
                      value: e.target.value,
                    },
                  })
                }
              >
                <option value="select">{__('Select a Collection')}</option>
                {featuredChannels &&
                  featuredChannels.map((list, i) => {
                    return (
                      <option key={i} value={list.id}>
                        {list.value.title}
                      </option>
                    );
                  })}
              </select>
            </div>
          )}
          {(section.type === 'content' || section.type === 'playlists') && (
            <div className="home-section-header-option">
              <label>{__('Order By')}</label>
              <select
                name="order_by"
                value={(section.order_by && section.order_by[0]) || 'release_time'}
                onChange={(e) =>
                  handleEditCollection({
                    change: {
                      field: e.target.name,
                      value: e.target.value,
                    },
                  })
                }
              >
                <option value="release_time">{__('New')}</option>
                <option value="trending_group">{__('Trending')}</option>
                <option value="effective_amount">{__('Top')}</option>
              </select>
            </div>
          )}
          {section.type === 'featured' && (
            <>
              <div className="home-section-header-option">
                <label>{__('Search')}</label>
                <input
                  id="featured"
                  name="search"
                  value={searchQuery}
                  onChange={handleInputChange}
                  placeholder={__('Search')}
                />
              </div>
              <div className="home-section-header-option">
                <label>{__('Results')}</label>
                <select
                  name="claim_id"
                  value={section.claim_id || 'select'}
                  disabled={!searchResults}
                  onChange={(e) =>
                    handleEditCollection({
                      change: {
                        field: e.target.name,
                        value: e.target.value,
                      },
                    })
                  }
                >
                  <option value="select">{__('Select...')}</option>
                  {!isSearching && searchResults ? (
                    searchResults.map((result, i) => {
                      return (
                        <option key={i} value={result.claimId}>
                          {result.title}
                        </option>
                      );
                    })
                  ) : (
                    <option value="no_results">{__('No Results...')}</option>
                  )}
                </select>
              </div>
            </>
          )}
        </div>
      )}
      {isLoading && (
        <div className="home-section-content">
          <div className="section">
            <h2 className="home-section-title">{__('Loading...')}</h2>
            <section className="claim-grid">
              {Array.from({ length: 12 }, (_, i) => (
                <ClaimPreviewTile key={i} placeholder="loading" pulse />
              ))}
            </section>
          </div>
        </div>
      )}
      {!isLoading &&
        !editMode &&
        ((requiresSearch && claimSearchResults && claimSearchResults.length === 0) ||
          (section.type === 'playlist' && !section.claim_id)) && (
          <div className="section">
            <div className="empty empty--centered">{__('No Content Found')}</div>
          </div>
        )}
      {section.type &&
        (section.claim_id ||
          collectionUrls ||
          (claimSearchResults && claimSearchResults.length > 0) ||
          (section.type === 'featured' && hasFeaturedClaim)) && (
          <div className="section">
            {section.type !== 'featured' ? (
              <>
                <h2 className="home-section-title">{collectionName || getTitle() || __('Loading...')}</h2>
                {(!featuredChannel || (featuredChannel && featuredChannel.value.uris.length > maxChannelsPerRow)) && (
                  <label className="show-more" onClick={() => handleViewMore(section)}>
                    {__('View More')}
                    <Icon icon={ICONS.ARROW_RIGHT} />
                  </label>
                )}
                {section.type !== 'channels'
                  ? (collectionUrls || claimSearchResults || collectionClaimIds) && (
                      <ClaimListDiscover
                        hideFilters
                        hideAdvancedFilter
                        hideLayoutButton
                        tileLayout
                        infiniteScroll={false}
                        useSkeletonScreen={false}
                        uris={collectionUrls || claimSearchResults}
                        maxClaimRender={maxClaimsInSection}
                        claimIds={collectionClaimIds}
                      />
                    )
                  : featuredChannel && (
                      <ChannelSection
                        key={'featured-channels'}
                        uris={featuredChannel && featuredChannel.value.uris.slice(0, maxChannelsPerRow)}
                        channelId={channelClaimId}
                      />
                    )}
              </>
            ) : (
              <FeaturedSection
                uri={singleClaimUri || (claimSearchResults && claimSearchResults[0])}
                claimId={section.claim_id}
              />
            )}
          </div>
        )}
    </div>
  );
}

export default HomeTabSection;
